-- Bat database (Phase 6): product lines, lineage notes for predecessors outside the catalog, published external
-- reviews, manufacturer warranty terms, release-date sources and a public market summary for the price guide.
-- Additive and safe to run more than once. Data is loaded by supabase/seed/bat-database.sql
-- (generated by scripts/build-bat-database-seed.mjs).

-- ---------------------------------------------------------------------------
-- Product lines ("families"): a manufacturer's line across years and versions, for example Miken Freak.
-- ---------------------------------------------------------------------------

create table if not exists public.product_lines (
  id text primary key check (id ~ '^[a-z0-9-]+$'),
  manufacturer_id uuid references public.manufacturers (id) on delete set null,
  name text not null check (char_length(name) between 1 and 120),
  aliases text[] not null default '{}',
  -- Short, sourced remarks about the line from the research notes (not performance claims).
  notes text[] not null default '{}',
  created_at timestamptz not null default now()
);

create index if not exists product_lines_manufacturer_idx on public.product_lines (manufacturer_id);

alter table public.products
  add column if not exists product_line_id text references public.product_lines (id) on delete set null,
  -- Lineage research for this model, including a predecessor that is not in the catalog (so there is no product
  -- to link). Shape: {predecessor_name, predecessor_in_catalog, changes[], confidence, basis, sources[]}.
  add column if not exists lineage_note jsonb check (lineage_note is null or jsonb_typeof(lineage_note) = 'object'),
  -- Where release_date / release_status came from (for example a retailer's expected ship date). Null when unknown.
  add column if not exists release_date_source text check (release_date_source is null or char_length(release_date_source) <= 500);

create index if not exists products_product_line_idx on public.products (product_line_id);

-- ---------------------------------------------------------------------------
-- Warranty terms per manufacturer. Null means "not on file", never "no warranty".
-- ---------------------------------------------------------------------------

alter table public.manufacturers
  add column if not exists warranty_summary text check (warranty_summary is null or char_length(warranty_summary) <= 600),
  add column if not exists warranty_source text check (warranty_source is null or char_length(warranty_source) <= 300),
  add column if not exists warranty_source_url text check (warranty_source_url is null or warranty_source_url ~ '^https?://');

-- ---------------------------------------------------------------------------
-- Published external reviews: tested reviews, review sites, retailer write-ups, customer ratings, videos.
-- We store the title, source, link and a short summary of what the source says; never our own score.
-- A review links to specific models and/or to whole product lines.
-- ---------------------------------------------------------------------------

create table if not exists public.published_reviews (
  id uuid primary key default gen_random_uuid(),
  -- Stable id from data/reviews.json (for example 'r001'), so the seed can be re-run.
  source_key text unique check (source_key ~ '^[a-z0-9_-]+$'),
  kind text not null check (kind in ('expert', 'site', 'retailer', 'customer', 'video')),
  title text not null check (char_length(title) between 3 and 300),
  url text not null check (url ~ '^https?://'),
  source text not null check (char_length(source) between 2 and 120),
  -- The source's own rating, as text ("8.0/10", "4.7/5 from 31 ratings"). Never computed by us.
  rating_text text check (rating_text is null or char_length(rating_text) <= 80),
  published_on date check (published_on is null or published_on between date '1990-01-01' and date '2100-12-31'),
  summary text check (summary is null or char_length(summary) <= 2000),
  status text not null default 'published' check (status in ('published', 'hidden')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

drop trigger if exists published_reviews_updated_at on public.published_reviews;
create trigger published_reviews_updated_at before update on public.published_reviews
  for each row execute function public.set_updated_at();

create table if not exists public.published_review_products (
  review_id uuid not null references public.published_reviews (id) on delete cascade,
  product_id uuid not null references public.products (id) on delete cascade,
  primary key (review_id, product_id)
);
create index if not exists published_review_products_product_idx on public.published_review_products (product_id);

create table if not exists public.published_review_lines (
  review_id uuid not null references public.published_reviews (id) on delete cascade,
  product_line_id text not null references public.product_lines (id) on delete cascade,
  primary key (review_id, product_line_id)
);
create index if not exists published_review_lines_line_idx on public.published_review_lines (product_line_id);

-- ---------------------------------------------------------------------------
-- Row Level Security: public read, server-only writes (no write policies, and no write grants either).
-- ---------------------------------------------------------------------------

alter table public.product_lines enable row level security;
alter table public.published_reviews enable row level security;
alter table public.published_review_products enable row level security;
alter table public.published_review_lines enable row level security;

revoke insert, update, delete, truncate on public.product_lines, public.published_reviews,
  public.published_review_products, public.published_review_lines from anon, authenticated;
grant select on public.product_lines, public.published_reviews, public.published_review_products,
  public.published_review_lines to anon, authenticated;

drop policy if exists "Product lines are public" on public.product_lines;
create policy "Product lines are public" on public.product_lines for select using (true);

drop policy if exists "Published reviews are public" on public.published_reviews;
create policy "Published reviews are public" on public.published_reviews
  for select using (status = 'published' or public.has_role('moderator'));

drop policy if exists "Review links to published models are public" on public.published_review_products;
create policy "Review links to published models are public" on public.published_review_products
  for select using (
    (exists (select 1 from public.published_reviews r where r.id = review_id and r.status = 'published')
      and exists (select 1 from public.products p where p.id = product_id and p.catalog_status = 'published'))
    or public.has_role('moderator'));

drop policy if exists "Review links to lines are public" on public.published_review_lines;
create policy "Review links to lines are public" on public.published_review_lines
  for select using (
    exists (select 1 from public.published_reviews r where r.id = review_id and r.status = 'published')
    or public.has_role('moderator'));

-- ---------------------------------------------------------------------------
-- Market summary per published model, for the price guide list. Asking prices (live listings) and verified
-- sold prices (price_history rows with verified_transaction) are kept in separate columns and never combined.
-- Runs with the owner's rights like the other public views, so it filters to public rows itself and returns
-- aggregates only.
-- ---------------------------------------------------------------------------

create or replace view public.product_market_summary
with (security_barrier = true)
as
with asking as (
  select l.product_id,
    count(*)::int as active_listings,
    min(l.asking_price_cents)::int as asking_min_cents,
    max(l.asking_price_cents)::int as asking_max_cents,
    round(avg(l.asking_price_cents))::int as asking_avg_cents
  from public.equipment_listings l
  where l.listing_status = 'active' and l.product_id is not null
  group by l.product_id
),
sold as (
  select h.product_id,
    count(*)::int as verified_sales,
    min(h.sale_date) as first_sale_date,
    max(h.sale_date) as last_sale_date
  from public.price_history h
  where h.verified_transaction
  group by h.product_id
)
select
  p.id as product_id,
  coalesce(a.active_listings, 0) as active_listings,
  a.asking_min_cents,
  a.asking_max_cents,
  a.asking_avg_cents,
  coalesce(s.verified_sales, 0) as verified_sales,
  s.first_sale_date,
  s.last_sale_date
from public.products p
left join asking a on a.product_id = p.id
left join sold s on s.product_id = p.id
where p.catalog_status = 'published';

revoke all on public.product_market_summary from anon, authenticated;
grant select on public.product_market_summary to anon, authenticated;
